// Forge 1.12.2 → 1.16.5 : changements majeurs
// @Mod(modid=...) → @Mod("monmod")
// proxy SidedProxy → DistExecutor
// ItemStack(item, count, meta) → ItemStack(item, count)  (pas de meta)
// net.minecraft.item.Item.ToolMaterial → Tiers
// net.minecraft.block.material.Material → BlockBehaviour.Properties

// Forge 1.16.5 → 1.18.2 : renommages Mojang
// World          →  Level
// ServerWorld    →  ServerLevel
// TileEntity     →  BlockEntity
// PlayerEntity   →  Player
// MatrixStack    →  PoseStack
// CompoundNBT    →  CompoundTag
// ItemStack.getTag()     →  ItemStack.getTag()  (inchangé)
// World.isRemote         →  Level.isClientSide

// Forge 1.18.2 → 1.19.2
// player.sendMessage(Component, UUID)  →  player.sendSystemMessage(Component)
// ITextComponent                       →  Component
// StringTextComponent                  →  Component.literal(...)
// TranslationTextComponent             →  Component.translatable(...)
// ChatFormatting  →  inchangé

// Forge 1.19.2 → 1.20.1 : renommages majeurs
// PoseStack remplacé par GuiGraphics dans Screen.render() et tous les rendus GUI
// entity.level     →  entity.level()   (méthode, plus champ public)
// CreativeModeTab.builder() + BuildCreativeModeTabContentsEvent pour onglets créatifs

// 1.20.1 : signature de render() dans un Screen
@Override
public void render(GuiGraphics g, int mouseX, int mouseY, float delta) {
    this.renderBackground(g);
    super.render(g, mouseX, mouseY, delta);
    g.drawString(font, "Titre", 28, 6, 0x404040, false);
}

// Forge 1.20.1 → NeoForge 1.21.1 : renommer tous les imports
// net.minecraftforge.*    →  net.neoforged.neoforge.*
// net.minecraftforge.fml.* →  net.neoforged.fml.*
// Bus.FORGE  →  Bus.GAME
// mods.toml  →  neoforge.mods.toml

// NeoForge 1.21.1 : IEventBus injecté automatiquement
@Mod("monmod")
public class MonMod {
    public MonMod(IEventBus modBus) {  // injecté par NeoForge
        ModItems.ITEMS.register(modBus);
        ModBlocks.BLOCKS.register(modBus);
    }
}
// Plus besoin de FMLJavaModLoadingContext.get().getModEventBus()

// NeoForge 1.21.1+ : Data Components remplacent le NBT pour les items
// Lire :
boolean actif = stack.getOrDefault(ModComponents.MAGNET.get(), false);
// Écrire :
stack.set(ModComponents.MAGNET.get(), true);
// Mettre à jour (1.21.8+) :
stack.update(ModComponents.KILLS.get(), 0, n -> n + 1);

// NeoForge 1.21.8 : DeferredRegister.Items helper
public static final DeferredRegister.Items ITEMS =
    DeferredRegister.createItems(MOD_ID); // inchangé côté API
// Enregistrement identique à 1.21.1

// Fabric : point d'entrée principal
public class MonMod implements ModInitializer {
    @Override
    public void onInitialize() {
        ModItems.register();
        ModBlocks.register();
        ModEvents.register();
    }
}
// Déclaré dans fabric.mod.json sous "entrypoints" → "main"

// Fabric : pas de DeferredRegister
Registry.register(
    Registries.ITEM,
    new Identifier("monmod", "rubis"),
    new Item(new Item.Settings().maxCount(64)));

Registry.register(
    Registries.BLOCK,
    new Identifier("monmod", "ruby_block"),
    new Block(AbstractBlock.Settings.of().strength(3.0f)));

// Fabric : s'abonner à un événement (callback, pas d'annotation)
PlayerBlockBreakEvents.BEFORE.register(
    (world, player, pos, state, be) -> {
        return true; // retourner false pour annuler
    }
);

ServerTickEvents.END_SERVER_TICK.register(server -> {
    // chaque tick serveur
});

// Fabric : enregistrement côté client
public class MonModClient implements ClientModInitializer {
    @Override
    public void onInitializeClient() {
        // enregistrement renderer entité, écrans, etc.
    }
}
// Déclaré dans fabric.mod.json sous "entrypoints" → "client"
